    # Recolor a disconnected object having the same normalized silhouette as
    # the largest connected object of a color that also has a singleton marker.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
