def transform(grid):
    # Recolor a disconnected object having the same normalized silhouette as
    # the largest connected object of a color that also has a singleton marker.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c))
            for y,x in q:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            comps.append((color,q))
    # A color with a singleton plus a larger component supplies the target color.
    prototypes=[]
    for color in {c for c,q in comps}:
        groups=[q for c,q in comps if c==color]
        if len(groups)>1 and any(len(q)==1 for q in groups):
            prototypes.append((color,max(groups,key=len)))
    def shape(q):
        mr=min(r for r,c in q); mc=min(c for r,c in q)
        return frozenset((r-mr,c-mc) for r,c in q)
    out=[row[:] for row in grid]
    for target_color, proto in prototypes:
        ps=shape(proto)
        for color,q in comps:
            if color!=target_color and len(q)>1 and shape(q)==ps:
                for r,c in q: out[r][c]=target_color
    return out

