def transform(grid):
    # Recolor non-background components whose exact normalized silhouette
    # matches another color's component, using the matching component's color.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set(); comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen: continue
            q = [(r,c)]; seen.add((r,c))
            for y,x in q:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b = y+dy,x+dx
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == color and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            mr, mc = min(y for y,x in q), min(x for y,x in q)
            shape = frozenset((y-mr,x-mc) for y,x in q)
            comps.append((color,q,shape))
    out = [row[:] for row in grid]
    # Matching shapes of distinct colors are treated as duplicate instances;
    # the larger shape's color is the reference when a tie occurs.
    byshape = {}
    for color,q,shape in comps:
        byshape.setdefault(shape, []).append((color,q))
    for matches in byshape.values():
        colors = {color for color,q in matches}
        if len(colors) < 2: continue
        target = max(matches, key=lambda item: len(item[1]))[0]
        for color,q in matches:
            if color != target:
                for r,c in q: out[r][c] = target
    return out
